using System;
using System.IO;
using System.Diagnostics;
using System.Linq;
using System.Runtime.CompilerServices;
using CircuitoStudio;
class LegacyXlsTests {
 static int n;static void Check(bool b,string message){n++;if(!b)throw new Exception(message);}
 static void Reject(Action action){try{action();}catch(InvalidDataException){n++;return;}throw new Exception("Invalid XLS accepted");}
 [MethodImpl(MethodImplOptions.NoInlining)] static bool VerifyXlsx(string path){using(var stream=File.OpenRead(path))using(var reader=ExcelDataReader.ExcelReaderFactory.CreateOpenXmlReader(stream)){if(!reader.Read()||reader.GetString(0)!="Manufacturer"||!reader.Read())return false;return reader.GetString(0)=="Fábrica ç"&&reader.GetDouble(4)==12.5;}}
 static void Main(string[] args){if(args.Length==2&&args[0]=="--isolated"){var d=CatalogData.ImportXls(args[1]);if(d.Items.Count!=1||d.Items[0].RatedA!=12.5)throw new Exception("Isolated import failed");Console.WriteLine("ISOLATED PASS");return;}
  string fixtures=Path.GetFullPath(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"..","amostras-testes","xls"));string dir=Path.Combine(Path.GetTempPath(),"legacy-xls-tests-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(dir);try{
   string valid=Path.Combine(fixtures,"equipamentos.xls");var rows=LegacyXls.ReadRows(valid);Check(rows.Count==2&&rows[0].Length==11,"Read binary BIFF8 fixture from independent writer");Check(rows[1][0]=="Fábrica ç"&&rows[1][2]=="Descrição\nlinha","Unicode and newline read correctly");Check(rows[1][4]=="12.5","Numeric cells converted invariantly");var catalog=CatalogData.ImportTable(valid);Check(catalog.Items.Count==1&&catalog.Items[0].RatedA==12.5&&catalog.Items[0].Reference=="REF001","Equipment XLS mapped and validated");var cables=CableSelection.ImportTable(Path.Combine(fixtures,"cabos.xls"));Check(cables.Count==1&&cables[0].Name=="Cabo Ω"&&cables[0].SectionMm2==10&&Math.Abs(cables[0].ReactanceOhmKm-.08)<1e-9,"Cable XLS units preserved");Check(CatalogData.ImportXls(Path.Combine(fixtures,"modelo-vazio.xls")).Items.Count==0,"Header-only template supported");Check(CatalogData.ImportXls(Path.Combine(fixtures,"fonte-vazia.xls")).Items[0].Source=="","Optional trailing blank source preserved");
   Reject(delegate{CatalogData.ImportTable(Path.Combine(fixtures,"duplicados.xls"));});Reject(delegate{CatalogData.ImportTable(Path.Combine(fixtures,"numero-invalido.xls"));});Reject(delegate{CatalogData.ImportTable(Path.Combine(fixtures,"cabecalho-invalido.xls"));});Reject(delegate{CatalogData.ImportTable(Path.Combine(fixtures,"erro-celula.xls"));});Reject(delegate{LegacyXls.ReadRows(Path.Combine(fixtures,"colunas-excedentes.xls"));});Reject(delegate{CatalogData.ImportTable(Path.Combine(fixtures,"texto-longo.xls"));});string generated=Path.Combine(dir,"independent-reader.xlsx");CatalogData.ExportXlsx(catalog,generated);Check(VerifyXlsx(generated),"Generated XLSX verified by independent OpenXML reader");
   string large=Path.Combine(dir,"large.csv");using(var output=File.Create(large))output.SetLength(32*1024*1024+1);Reject(delegate{CatalogData.ImportCsv(large);});Reject(delegate{CableSelection.ImportCsv(large);});Reject(delegate{LegacyXls.ReadRows(large);});Reject(delegate{XlsxWorkbook.ReadRows(large);});
   string fake=Path.Combine(dir,"fake.xls");File.WriteAllText(fake,CatalogData.Header);Reject(delegate{CatalogData.ImportXls(fake);});Reject(delegate{CatalogData.ImportTable(Path.Combine(dir,"unsupported.exe"));});Check(EmbeddedComponents.LicenseText().Contains("Copyright (c) 2014 ExcelDataReader")&&EmbeddedComponents.LicenseText().Contains(".NET Foundation"),"Licenses embedded in executable");
   string isolated=Path.Combine(dir,"isolated");Directory.CreateDirectory(isolated);string runner=Path.Combine(isolated,"LegacyXlsTests.exe");File.Copy(typeof(LegacyXlsTests).Assembly.Location,runner);Check(Directory.GetFiles(isolated).Length==1,"Isolated directory contains executable only");using(var p=Process.Start(new ProcessStartInfo(runner,"--isolated \""+valid+"\""){UseShellExecute=false,CreateNoWindow=true,WorkingDirectory=isolated,RedirectStandardOutput=true,RedirectStandardError=true})){if(!p.WaitForExit(15000)){p.Kill();throw new Exception("Isolated runtime timed out");}string output=p.StandardOutput.ReadToEnd(),error=p.StandardError.ReadToEnd();Check(p.ExitCode==0&&output.Contains("ISOLATED PASS"),"Embedded runtime loads without external DLL: "+error);}
   Console.WriteLine("PASS: "+n+" legacy XLS assertions, including isolated executable");
  }finally{Directory.Delete(dir,true);}
 }
}
